python3 << 'PYEOF'
import json, uuid

# Load all definitions
with open('/tmp/def_ixp_contracts.json') as f:
    ixp_node = json.load(f)['Data']['Node']
with open('/tmp/def_end.json') as f:
    end_node = json.load(f)['Data']['Node']
with open('/tmp/def_script.json') as f:
    script_node = json.load(f)['Data']['Node']
with open('/tmp/def_hitl.json') as f:
    hitl_node = json.load(f)['Data']['Node']

# IxP inputDefaults — fix modelName (it's null, use modelDisplayName)
ixp_defaults = ixp_node['inputDefaults']
ixp_model_blob = dict(ixp_defaults['model'])
if not ixp_model_blob.get('modelName'):
    ixp_model_blob['modelName'] = ixp_model_blob['modelDisplayName']

ixp_out = ixp_node['outputDefinition']

# Read the scaffolded flow to preserve id, version, name, solutionId, projectId
flow_path = '/work/output/artifacts/skill-flow-ixp-routing/contracts/ContractExtractionSolution/ContractExtraction/ContractExtraction.flow'
with open(flow_path) as f:
    existing = json.load(f)

flow = {
    "id": existing["id"],
    "version": existing["version"],
    "name": existing["name"],
    "nodes": [
        # 1. Manual trigger (keep existing)
        {
            "id": "start",
            "type": "core.trigger.manual",
            "typeVersion": "1.0",
            "display": {"label": "Start — Receive Contract PDF"},
            "inputs": {
                "entryPointId": existing["nodes"][0]["inputs"]["entryPointId"],
                "isDefaultEntryPoint": True
            }
        },
        # 2. IxP extraction node
        {
            "id": "extractContractFields",
            "type": ixp_node["nodeType"],
            "typeVersion": ixp_node["version"],
            "display": {"label": "Extract Contract Fields (IxP)"},
            "inputs": {
                "model": ixp_model_blob,
                "modelName": ixp_defaults["modelName"],
                "description": ixp_defaults.get("description", ""),
                "projectName": ixp_defaults["projectName"],
                "versionTag": "",
                "folderKey": ixp_defaults["folderKey"],
                "folderName": ixp_defaults["folderName"],
                "fileRef": "=js:$vars.start.output.contractFile",
                "pageRange": ""
            },
            "outputs": {
                "output": ixp_out["output"],
                "error":  ixp_out["error"]
            }
        },
        # 3. Script: parse extracted fields
        {
            "id": "parseContractFields",
            "type": "core.action.script",
            "typeVersion": "1.0",
            "display": {"label": "Parse Party Names, Effective Date & Termination Clause"},
            "inputs": {
                "script": (
                    "var fields = ($vars.extractContractFields.output && "
                    "$vars.extractContractFields.output.ExtractionResult && "
                    "$vars.extractContractFields.output.ExtractionResult.ResultsDocument && "
                    "$vars.extractContractFields.output.ExtractionResult.ResultsDocument.Fields) "
                    "? $vars.extractContractFields.output.ExtractionResult.ResultsDocument.Fields : [];\n"
                    "function getField(name) {\n"
                    "  var f = fields.find(function(x){ return x.FieldName === name; });\n"
                    "  return f && f.Values && f.Values.length > 0 ? f.Values[0] : null;\n"
                    "}\n"
                    "return {\n"
                    "  partyNames: getField('Party Names') || getField('Employee Name') || getField('Employer Name'),\n"
                    "  effectiveDate: getField('Effective Date') || getField('Start Date'),\n"
                    "  terminationClause: getField('Termination Clause') || getField('Termination')\n"
                    "};"
                )
            },
            "outputs": {
                "output": {
                    "type": "object",
                    "description": "Parsed contract fields",
                    "source": "=result.response",
                    "var": "output",
                    "properties": {
                        "partyNames":        {"type": "string"},
                        "effectiveDate":     {"type": "string"},
                        "terminationClause": {"type": "string"}
                    }
                },
                "error": {
                    "type": "object",
                    "description": "Error information if the script fails",
                    "source": "=result.Error",
                    "var": "error"
                }
            }
        },
        # 4. HITL approval step
        {
            "id": "contractApproval",
            "type": "uipath.human-in-the-loop.quick-form",
            "typeVersion": "1.0",
            "display": {"label": "Contract Approval Review"},
            "inputs": {
                "schema": {
                    "schemaId": str(uuid.uuid4()),
                    "fields": [
                        {
                            "id": "partyNames",
                            "label": "Party Names",
                            "type": "text",
                            "direction": "input",
                            "binding": "vars.parseContractFields.output.partyNames"
                        },
                        {
                            "id": "effectiveDate",
